<?php
require_once __DIR__.'/../app/bootstrap.php';require_login();$user=current_user();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim((string)($_POST['full_name']??''));$email=filter_var(trim((string)($_POST['email']??'')),FILTER_VALIDATE_EMAIL);$new=(string)($_POST['new_password']??'');$current=(string)($_POST['current_password']??'');if($name===''||!$email)$error='Enter a name and valid email.';else{try{$pdo=db();$st=$pdo->prepare('SELECT password_hash FROM users WHERE id=?');$st->execute([$user['id']]);$hash=$st->fetchColumn();if($new!==''&&(!password_verify($current,(string)$hash)||strlen($new)<10))$error='To change password, enter your current password and use at least 10 characters for the new password.';else{$params=[$name,$email];$sql='UPDATE users SET full_name=?,email=?';if($new!==''){$sql.=',password_hash=?';$params[]=password_hash($new,PASSWORD_DEFAULT);}$sql.=' WHERE id=?';$params[]=$user['id'];$pdo->prepare($sql)->execute($params);$_SESSION['user']['full_name']=$name;$_SESSION['user']['email']=$email;flash('success','Profile updated.');redirect('profile.php');}}catch(PDOException $e){$error='Could not update profile. That email may already be used.';}}}
$pageTitle='My profile';require __DIR__.'/includes/header.php';?><div class="welcome-row"><div><h2>Account settings</h2><p class="muted">Update your personal details and password.</p></div></div><section class="panel form-panel"><form method="post" class="member-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><?php if($error): ?><div class="alert error"><?= e($error) ?></div><?php endif; ?><div class="form-grid"><label>Full name *<input name="full_name" required value="<?= e($user['full_name']) ?>"></label><label>Email address *<input type="email" name="email" required value="<?= e($user['email']) ?>"></label><label>Role<input value="<?= e(str_replace('_',' ',$user['role'])) ?>" disabled></label></div><div class="form-section-title"><span>🔒</span><div><h3>Change password</h3><p class="muted">Leave blank to keep your current password.</p></div></div><div class="form-grid"><label>Current password<input type="password" name="current_password" autocomplete="current-password"></label><label>New password<input type="password" name="new_password" minlength="10" autocomplete="new-password"></label></div><div class="form-actions"><button class="btn primary" type="submit">Save profile →</button></div></form></section><?php require __DIR__.'/includes/footer.php'; ?>
